module parity_8bit (
    input [7:0] in,
    output out
);
    parameter PARITY_TYPE = "EVEN";

    assign out = (PARITY_TYPE == "EVEN") ? ~^in : 
                 (PARITY_TYPE == "ODD") ? ^in : 
                 1'b0;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_sel1, not_sel0;
    wire en0, en1, en2, en3;
    wire term0, term1, term2, term3;

    // Invert select signals
    not (not_sel1, sel[1]);
    not (not_sel0, sel[0]);

    // Generate enable signals
    and (en0, not_sel1, not_sel0);
    and (en1, not_sel1, sel[0]);
    and (en2, sel[1], not_sel0);
    and (en3, sel[1], sel[0]);

    // Generate AND terms for each input
    and (term0, in[0], en0);
    and (term1, in[1], en1);
    and (term2, in[2], en2);
    and (term3, in[3], en3);

    // Combine terms to get output
    or (out, term0, term1, term2, term3);
endmodule

module majority (
    input a, b, c,
    output out
);
    wire [2:0] sum = a + b + c;
    assign out = (sum >= 1) && (sum <= 2);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray = (binary ^ (binary >> 1)) ^ 4'b1100;
endmodule

module eq_comparator (
