module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3] == 1'b0) begin
        code = 2'b11;
    end else if (in[2] == 1'b0) begin
        code = 2'b10;
    end else if (in[1] == 1'b0) begin
        code = 2'b01;
    end else begin
        code = 2'b00;
    end
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    parameter s0 = 2'b00,
             s1 = 2'b01,
             s2 = 2'b10;

    reg [1:0] current_state, next_state;
    wire [1:0] next_state;

    // Next state logic
    assign next_state[0] = (current_state[1] & ~current_state[0]) | 
                           (~current_state[1] & current_state[0]) | 
                           (~current_state[1] & ~current_state[0]);

    assign next_state[1] = current_state[1] | 
                            (~current_state[1] & ~current_state[0]);

    // State register
    always @(posedge clk) begin
        if (reset)
            current_state <= s0;
        else
            current_state <= next_state;
    end

    assign state = current_state;
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg [2:0] state, next_state;
    parameter [2:0] RED   = 3'b001,
                    YELLOW = 3'b010,
                    GREEN  = 3'b100;

    // State register with synchronous reset
    always @(posedge clk) begin
        if (reset)
            state <= RED;
        else
            state <= next_state;
    end

    // Next state logic (cycles through states)
    always @(*) begin
        case (state)
            RED:   next_state = YELLOW;
            YELLOW next_state = GREEN;
            GREEN  next_state = RED;
            default: next_state = RED;
        endcase
    end

    // Output logic (one-hot)
    assign light = state;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State definitions
    parameter [1:0] SNT  = 2'b00,
                    WNT  = 2'b01,
                    BOTH = 2'b10;

    // Timing parameters (example values, adjust as needed)
    parameter SNT_W = 20,
              WNT_S = 20,
              BOTH_W = 20;

    reg [1:0] current_state, next_state;
    reg [2:0] counter;
    reg prev_up, prev_down;
    wire up_rise = ~prev_up & up_request;
    wire down_rise = ~prev_down & down_request;

    // Edge detection for requests
    always @(posedge clk) begin
        if (reset) begin
            prev_up <= 1'b0;
            prev_down <= 1'b0;
        end else begin
            prev_up <= up_request;
            prev_down <= down_request;
        end
    end

    // State transition and counter logic
    always @(posedge clk) begin
        if (reset) begin
            current_state <= SNT;
            counter <= 1;
        end else begin
            if (current_state != next_state) begin
                // Capture current counter value on state change
                case (current_state)
                    SNT:  counter <= WNT;
                    WNT:  counter <= SNT_W;
                    BOTH: counter <= WNT;
                    default: counter <= 1;
                endcase
            end else begin
                if (counter != 0)
                    counter <= counter - 1;
            end
        end
    end

    // Next state logic
    reg [1:0] next_state_comb;
    always @(*) begin
        case (current_state)
            SNT: begin
                if (up_request)       next_state_comb = WNT;
                else if (down_request) next_state_comb = SNT_W;
                else                next_state_comb = SNT;
            end
            WNT: begin
                if (down_request)   next_state_comb = SNT;
                else if (up_request) next_state_comb = BOTH;
                else               next_state_comb = WNT;
            end
            SNT_W: begin
                if (up_request)     next_state_comb = BOTH;
                else if (down_request) next_state_comb = WNT;
                else               next_state_comb = SNT_W;
            end
            BOTH: begin
                if (up_request)     next_state_comb = BOTH;
                else if (down_request) next_state_comb = BOTH;
                else               next_state_comb = BOTH;
            end
            default: next_state_comb = SNT;
        endcase
    end

    assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // Define one-hot encoded state parameters
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    // State assignments (mutually exclusive)
    assign state = (reset) ? S0 : 
                  (coin_inserted) ? S1 : 
                  (item_selected) ? S2 : S0;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

wire [7:0] abs_in0 = in_0[7] ? -in_0 : in_0;
wire [3:0] abs_in1 = in_1[3] ? -in_1 : in_1;

reg signed [8:0] product;

always @(*) begin
    case (abs_in1)
        4'd0: product = 9'sd0;
        4'd1: product = {{2'b00, in_0[7]} & {9{in_0[7]}} } << 1;
        4'd2: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 2;
        4'd3: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 3;
        4'd4: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 4;
        4'd5: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 5;
        4'd6: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 6;
        4'd7: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 7;
        4'd8: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 8;
        4'd9: product = $signed({{2'b00, in_0[7]} & {9{in_0[7]}} }) << 9;
        default: product = 9'sd0;
    endcase
end

assign out = in_0[7] ? -product : product;

endmodule

