module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

    function signed [15:0] relu_func;
        input signed [15:0] in;
        integer i;
        begin
            for (i=0; i<16; i=i+1) begin
                if (i[0]) // Check if any bit is 1
                    i = 16'hffff;
            end
            relu_func = (in[0]) ? 16'hffff : in;
        end
    endfunction

    assign out = relu_func(in_0);

endmodule

module caesar_cipher (
