module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [2:0] A = data_in[7:5];
    wire [2:0] S1 = data_in[2:0];
    wire [2:0] D = A;
    wire [2:0] S2 = D ^ {KEY[3], 3'b000} ^ 3'b001;
    wire [2:0] E = S2;
    wire [2:0] S3 = E ^ {KEY[0], 3'b000} ^ 3'b001;
    wire [2:0] F = S3;

    assign data_out = {A, S1, D, S2, E, S3, F};
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    parameter N = 0;
    localparam COUNTER_WIDTH = (N == 0) ? 1 : $clog2(N);
    reg [COUNTER_WIDTH-1:0] counter_reg;

    always @(posedge clk) begin
        if (N > 0) begin
            if (rst) begin
                counter_reg <= {COUNTER_WIDTH{1'b0}};
            end else begin
                if (counter_reg == (N/2 -1)) begin
                    counter_reg <= 0;
                end else begin
                    counter_reg <= counter_reg + 1;
                end
            end
        end else begin
            counter_reg <= 0;
        end
    end

    assign clk_out = (N > 0) ? (counter_reg[COUNTER_WIDTH-1]) : 1'b0;

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    reg eq_bit3, eq_bit2, eq_bit1, eq_bit0;
    reg gt_bit3, gt_bit2, gt_bit1, gt_bit0;
    wire [3:0] eq;
    reg [3:0] a_xor_b;

    // Generate a_xor_b using XNOR (1ns delay)
    assign #(1) a_xor_b = a ~^ b;

    // Compute equality bits with 1ns delay
    genvar i;
    generate
        for (i=0; i<4; i=i+1) begin : gen_eq
            and #1 and_eq3(eq_bit3, a_xor_b[3], a_xor_b[3]);
            and #1 and_eq2(eq_bit2, a_xor_b[2], a_xor_b[2]);
            and #1 and_eq1(eq_bit1, a_xor_b[1], a_xor_b[1]);
            and #1 and_eq0(eq_bit0, a_xor_b[0], a_xor_b[0]);
        end
    endgenerate
    assign eq = {eq_bit3, eq_bit2, eq_bit1, eq_bit0};

    // Compute gt and lt with 2ns delay
    reg gt, lt;
    always @(*) begin
        {gt, lt} = (a > b) ? 2'b10 :
                   (a < b) ? 2'b01 :
                   2'b00;
    end
    assign #(2) {gt, lt} = {gt, lt};

    assign eq = &eq;
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    assign out = (enable ? 4'b1111 : 4'b0000) << in;

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
    wire [7:0] temp;
    assign temp = enable ? 8'b1 << in : 8'bzzzz_zzzz;
    assign out = ~temp;
endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

    wire n1, n2;

    nand #1 (n1, in, sel);
    nand #1 (out0, n1, n1);

    nand #1 (n2, in, ~sel);
    nand #1 (out1, n2, n2);

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    reg out0;
    reg out1;
    reg out2;
    reg out3;

    integer i;
    reg selected_bit;

    always @(*) begin
        case (sel)
            2'b00: selected_bit = out0;
            2'b01: selected_bit = out1;
            2'b10: selected_bit = out2;
            2'b11: selected_bit = out3;
            default: selected_bit = 1'b0;
        endcase
    end

    always @(*) begin
        if (in !== 1'b0 && in !== 1'b1) begin
            $display("Error: Invalid input %b", in);
            selected_bit = 1'bx;
        end else begin
            selected_bit = in;
        end
    end

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

reg [7:0] binary;
wire [7:0] gray;

// Binary counter with synchronous reset
always @(posedge clk) begin
    if (rst)
        binary <= 8'b0;
    else
        binary <= binary + 1;
end

// Convert binary to Gray code (binary ^ (binary >> 1))
assign gray = binary ^ (binary >> 1);

// Assign the output
assign count = gray;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
    wire feedback;
    assign feedback = ~q[3];

    assign q[0] = (rst) ? 1'b1 : (q[3] ^ feedback);
    assign q[1] = (rst) ? 1'b0 : q[0];
    assign q[2] = (rst) ? 1'b0 : q[1];
    assign q[3] = (rst) ? 1'b0 : q[2];
endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (rst) begin
            shift_reg <= 8'b0;
        end else begin
            if (load) begin
                shift_reg <= pin;
            end else begin
                shift_reg <= {1'b0, shift_reg[7:1]};
            end
        end
    end

    assign sout = rst ? 1'b0 : (load ? pin[0] : shift_reg[0]);

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

wire q3, q2, q1, q0;

assign q = {q3, q2, q1, q0};

assign q3 = ~ ( (q2 & q0) | (q2 & q1) | (q0 & q1) );
assign q2 = ~ ( (q1 & q0) | (q1 & q3) | (q0 & q3) );
assign q1 = ~ ( (q2 & q0) | (q2 & q3) | (q0 & q3) );
assign q0 = ~ ( (q1 & q3) | (q1 & q2) | (q3 & q2) );

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst) begin
        shift_reg <= 8'b0;
    end else begin
        shift_reg <= {shift_reg[6:0], sin}; // Shift left, append sin as LSB
    end
end

assign pout = shift_reg;

endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);
    reg [7:0] shift_reg;

    always @(posedge clk) begin
        if (rst) begin
            shift_reg <= 8'h00;
        end else begin
            shift_reg <= {shift_reg[6:0], sin};
        end
    end

    assign sout = shift_reg[7];
endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);
    reg [7:0] count_reg;

    assign count = count_reg;

    always @(posedge clk) begin
        if (rst) begin
            count_reg <= 8'd0;
        end else begin
            count_reg <= count_reg + 8'd1;
        end
    end
endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] r_reg;
  reg [2:0] g_reg;

  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      g_reg <= 3'b0;
    end
  end

  assign g = (resetn) ? g_reg : 3'bzz;

endmodule

module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);

  reg out_reg;

  // Task 1: Bind unused wire to undefined in a different module
  module OtherModule;
    wire undefined;
  end
  assign out_assign = undefined;

  // Task 2: Split continuous assignments
  wire [1:0] out_cont = 2'b10;
  wire [1:0] out_cont2 = 2'b01;

  // Task 3: Non-block assignments with assignments in always block
  always #1 non_block = out_cont;
  always #2 non_block2 = out_cont2;

  // Task 4: Block assignment in always block
  always #3 reg_block = out_cont;

  // Task 5: Task assigned to reg
  task task_example;
    task_example = 1'b1;
  endtask
  always #4 reg_task = task_example;

  // Task 6: Procedural block assigned to reg
  reg reg_procedure;
  always #5 begin
    reg_procedure = 1'b1;
  end

endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff

  // Combinational logic using assign statement
  assign out_assign = a & b;

  // Combinational logic using always block
  always @* begin
    out_always_comb = a | b;
  end

  // Sequential logic using always block and clock
  always @(posedge clk) begin
    out_always_ff <= ~(a ^ b);
  end

endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  // Hardcode the out_always output to 1
  always @* begin
    out_always = 1'b1;
  end

  // Assign out_assign using gate-level modeling
  assign out_assign = (a & {sel_b1, b}) | {sel_b2, 1'bz};

endmodule

module TopModule (
  input cpu_overheated,
  output reg shut_off_computer,
  input arrived,
  input gas_tank_empty,
  output reg keep_driving
);

  always @(*) begin
    if (cpu_overheated) begin
      shut_off_computer = 1'b1;
      keep_driving = 1'b0;
    end else begin
      if (gas_tank_empty) begin
        shut_off_computer = 1'b0;
        keep_driving = 1'b1;
      end else begin
        if (arrived) begin
          shut_off_computer = 1'b1;
          keep_driving = 1'b0;
        end else begin
          shut_off_computer = 1'b0;
          keep_driving = 1'b0;
        end
      end
    end
  end

endmodule

module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);

  always @(*) begin
    // Default assignments
    left = 1'b0;
    down = 1'b0;
    right = 1'b0;
    up = 1'b0;

    case (scancode[15:8])
      8'h1C: left = scancode[0];    // Left command (scancode[0] = 1)
      8'h1B: right = scancode[0];   // Right command (scancode[0] = 1)
      8'h1A: begin                 // Down command (scancode[0] = 1)
        down = scancode[0];
        up = scancode[1];          // Check scancode[1] for up
      end
      8'h19: begin                 // Up command (scancode[0] = 1)
        up = scancode[0];
        down = scancode[1];        // Check scancode[1] for down
      end
    endcase
  end

endmodule

module TopModule (
  input a,
  input b,
  output out
);
  wire not_a, not_b;
  wire and_ab, and_na;

  not(not_a, a);
  not(not_b, b);
  and(and_ab, a, b);
  and(and_na, not_a, not_b);
  or(out, and_ab, and_na);

endmodule

