  input ena,
  output logic q
);
  parameter [1:0] INIT = 2'b00,
                  S1 = 2'b01,
                  S2 = 2'b10,
                  S3 = 2'b11;

  reg [1:0] current_state, next_state;
  reg signed [2:0] d_ext;
  reg [1:0] next_state_reg;

  integer i;

  // Sign-extend d to 3 bits
  always @(*) begin
    d_ext = { {2{d}}, d };
  end

  // State transition and register
  always @(posedge ena) begin
    current_state <= next_state_reg;
  end

  // Combinational logic for next state
  always @(*) begin
    case (current_state)
      INIT: next_state_reg = S1;
      S1: begin
        if (d_ext[0])
          next_state_reg = S1;
        else if (d_ext[1])
          next_state_reg = S2;
        else if (d_ext[2])
          next_state_reg = S3;
        else
          next_state_reg = S1;
      end
      S2: next_state_reg = S2;
      S3: next_state_reg = S3;
      default: next_state_reg = INIT;
    endcase
  end

  // Output logic
  assign q = ena ? (current_state[1] ? 1'b1 : 1'b0) : 1'bx;

endmodule

