  // Internal wires for logical operations
  wire and_out;
  and (and_out, in1, in2);

  // Buffer and invert with specified delay
  reg out;
  always @(*) begin
    if ($delay(2,4)) // 2 rise (2), 4 fall (4)
      out = and_out;
    else
      out = and_out;
  end

  // Tri-state buffer with specified delay
  reg buffer;
  always @(*) begin
    if ($delay(1,2)) // 1 rise (1), 2 fall (2)
      buffer = A ? in1 : in2;
    else
      buffer = A ? in1 : in2;
  end

  // Continuous assignments with delays
  reg [WIDTH-1:0] vec;
  integer i;
  reg [WIDTH-1:0] shifted;

  always @(*) begin
    if ($delay(3,1)) // 3 rise (3), 1 fall (1)
      vec = {in1, in2, {WIDTH-2{1'b0}}};
    else
      vec = {in1, in2, {WIDTH-2{1'b0}}};
  end

  always @(*) begin
    if ($delay(1:1:1)) // 1 rise (1:1), fall (1)
      shifted = vec >> 1;
    else
      shifted = vec >> 1;
  end

  // Invert with rise/fall times using casez
  reg [WIDTH-1:0] inverted;
  integer [WIDTH-1:0] initial_value;

  always @(*) begin
    initial_value = {WIDTH{1'b0}};
    if (in1)
      initial_value = {WIDTH{1'bz}};
    else if (in2)
      initial_value = {WIDTH{1'bz}};
    else
      initial_value = 0;
  end

  always @(*) begin
    if ($delay(2:2:2)) // 2 rise (2), fall (2:2)
      inverted = ~initial_value;
    else
      inverted = ~initial_value;
  end

endmodule

