  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg current_state, next_state;
  reg [1:0] current_x, next_x;
  wire [1:0] next_x_total = next_x + 1;
  wire [1:0] next_x_total_mod = next_x_total % 3;
  wire bump_collision = (next_x_total_mod == 2'b00);

  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= 1'b0;
      current_x <= 2'b0;
    end else begin
      current_state <= next_state;
      current_x <= next_x;
    end
  end

  always @(*) begin
    next_state = current_state;
    next_x = current_x;
    case (current_state)
      S0: begin
        if (ground) begin
          case ({bump_left, bump_right})
            2'b10: begin
              if (bump_collision) begin
                next_state = S1;
                next_x = current_x;
              end else begin
                next_state = S0;
                next_x = current_x;
              end
            end
            2'b01: begin
              if (bump_collision) begin
                next_state = S1;
                next_x = current_x;
              end else begin
                next_state = S0;
                next_x = current_x;
              end
            end
            default: begin
              next_state = S0;
              next_x = current_x;
            end
          endcase
        end
      end
      S1: begin
        next_state = ground ? S1 : S0;
        if (ground) begin
          case ({bump_left, bump_right})
            2'b10: begin
              if (bump_collision) begin
                next_x = current_x;
              end else begin
                next_x = current_x - 1;
              end
            end
            2'b01: begin
              if (bump_collision) begin
                next_x = current_x;
              end else begin
                next_x = current_x + 1;
              end
            end
            default: begin
              next_x = current_x;
            end
          endcase
        end
      end
      default: next_state = S0;
    endcase
  end

  assign walk_left = (current_state == S1) && bump_left && !bump_collision;
  assign walk_right = (current_state == S1) && bump_right && !bump_collision;

  assign aaah = (current_state == S0 || current_state == S1) ? 1'b1 : 1'bx;

endmodule

