        genvar j;
        for (genvar j=1; j<8; j=j+1) begin: ADDER_LOOP
            assign sum[j] = a[j] + b[j] + carry[j];
            assign carry[j+1] = (a[j] & b[j]) | ((a[j] | b[j]) & carry[j]);
        end
    endgenerate

    // Final carry-out (carry[8])
    assign cout = carry[8];
endmodule

