endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Internal wires for inverted bits
    wire [3:0] A_nand = ~A;
    wire [3:0] B_nand = ~B;

    // Generate all necessary terms using AND and NOT for each comparison
    wire [3:0] A_gt_B;
    wire [3:0] A_eq_B;
    wire [3:0] A_lt_B;

    // A_gt_B terms (A_i > B_i using XNOR)
    genvar i;
    generate
        for (i=0; i<4; i=i+1) begin: check_gt
            wire not_A_i, notB_notB, or1_or2;
            and nand1 (not_A_i, A[i], A[i]);          // Invert A[i]
            and nand2 (notB_notB, B[i], B[i]);        // Invert B[i]
            and nand3 (or1_or2, not_A_i, notB_notB); // OR to get A_i > B_i
            not nand4 (A_gt_B[i], or1_or2, or1_or2); // Invert to get the term
        end
    endgenerate

    // A_eq_B terms (XNOR using AND/NOT)
    wire [3:0] a_nand_a, b_nand_b, term0_or0;
    wire [3:0] a_term, b_term;

    generate
        for (i=0; i<4; i=i+1) begin: check_eq
            not nand5 (a_nand_a, A[i], A[i]);    // Invert A[i]
            not nand6 (b_nand_b, B[i], B[i]);    // Invert B[i]
            and nand7 (term0_or0, a_nand_a, b_nand_b); // AND for equality
            not nand8 (A_eq_B[i], term0_or0, term0_or0); // Invert to get the term
        end
    endgenerate

    // A_lt_B terms (A_i < B_i using XNOR)
    wire [3:0] a_or_b, term1_or1;
    wire [3:0] a_term_or1, b_term_or1;

    generate
        for (i=0; i<4; i=i+1) begin: check_lt
            wire or1_or2;
            or nand9 (or1_or2, A[i], B[i]);        // OR of A[i] and B[i]
            and nand10 (a_term_or1, or1_or2, A[i]); // AND with A[i]
            and nand11 (b_term_or1, or1_or2, B[i]); // AND with B[i]
            not nand12 (A_lt_B[i], a_term_or1, a_term_or1); // Invert to get the term
        end
    endgenerate
endgenerate

    // Combine terms into outputs
    assign A_greater = |A_gt_B;
    assign A_equal = |A_eq_B;
    assign A_less = |A_lt_B;

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		rise <= 1'b0;
		down <= 1'b0;
	} else begin
		rise <= (~a) & a;
		down <= a & (~a);
	end
end

endmodule

module freq_divbyeven(
    input clk,
    input rst_n,
    output clk_div,
    parameter NUM_DIV = 6;
    reg [1:0] counter;

    assign clk_div = counter[1];

    always @(posedge clk) begin
        if (!rst_n) begin
            counter <= 2'b00;
        end else begin
            counter <= (counter == 2'b10) ? 2'b00 : counter + 1;
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

reg [7:0] instruction_reg;

// Update instruction register on clock edge
always @(posedge clk) begin
    if (rst) begin
        instruction_reg <= 8'b0;
    end else begin
        case (fetch)
            2'b10: instruction_reg <= data;
            default: ; // No action for other fetch values
        endcase
    end
end

// Split the instruction into its components
assign ins = instruction_reg[7:5];
assign ad1 = instruction_reg[4:0];
assign ad2 = instruction_reg[7:0];

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  always @(posedge clk) begin
    if (rst) begin
      out <= 4'b0;
    end else begin
      out <= {out[2:0], (out[3] ^ out[2])};
    end
  end
endmodule

module right_shifter(clk, q,d);  

    input  clk;  
    input  d;  
    output [7:0] q;  

    reg [7:0] shift_reg;  

    always @(posedge clk) begin  
        shift_reg <= {shift_reg[0], d};  
    end  

    assign q = shift_reg;  

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Synchronize data_en to clk_a domain
	reg [1:0] en_sync_a = 2'b0;
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			en_sync_a <= 2'b0;
		end else begin
			en_sync_a <= {en_sync_a[0], data_en};
		end
	end
	wire en_sync_a_meta = en_sync_a[1];

	// Synchronize data_en to clk_b domain
	reg [1:0] en_sync_b = 2'b0;
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			en_sync_b <= 2'b0;
		end else begin
			en_sync_b <= {en_sync_b[0], en_sync_a_meta};
		end
	end
	wire en_sync_b_meta = en_sync_b[1];

	// Detect rising edge of synchronized enable in clk_b domain
	reg en_sync_b_d = 0;
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			en_sync_b_d <= 0;
		end else begin
			en_sync_b_d <= en_sync_b_meta;
		end
	end
	wire en_sync_b_rise = ~en_sync_b_d & en_sync_b_meta;

	// Capture data_in in clk_a domain when data_en is high
	reg [3:0] data_reg = 0;
	reg en_sync_a_meta_reg = 0;
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			data_reg <= 0;
			en_sync_a_meta_reg <= 0;
		end else begin
			en_sync_a_meta_reg <= en_sync_a_meta;
			if (data_en) begin
				data_reg <= data_in;
			end
		end
	end

	// Update dataout with a detection delay of 1 cycle
	always @(posedge clk_b or negedge brstn) begin
		if (!brstn) begin
			dataout <= 0;
		end else begin
			// Detect rising edge of en_sync_b_rise (1 cycle delay)
			if (en_sync_b_rise) begin
				dataout <= data_reg;
			end
		end
	end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;
reg [1:0] current_state, next_state;

// State transition and reset handling
always @(posedge CLK or posedge RST) begin
    if (RST) begin
        current_state <= 2'b00;
    end else begin
        current_state <= next_state;
    end
end

// Next state logic
always @(*) begin
    case (current_state)
        2'b00: next_state = IN ? 2'b10 : 2'b00;
        2'b01: next_state = IN ? 2'b01 : 2'b00;
        2'b10: next_state = IN ? 2'b11 : 2'b00;
        2'b11: next_state = IN ? 2'b10 : 2'b00;
        default: next_state = 2'b00;
    endcase
end

// Output logic
always @(*) begin
    MATCH = (current_state == 2'b11);
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] shift_reg;

always @(posedge clk) begin
    if (!rst_n) begin
        shift_reg <= 4'b0;
    end else begin
        if (|d) begin
            shift_reg <= 4'b0;
        end else begin
            shift_reg <= {shift_reg[2:0], 1'b0};
        end
    end
end

assign dout = shift_reg[3];
assign valid_out = |shift_reg;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     reg [2:0] shift_reg;
     wire [2:0] next_shift_reg = {shift_reg[1:0], data_in};

     always @(posedge clk) begin
        if (!rst_n) begin
            shift_reg <= 3'b000;
        end else begin
            shift_reg <= next_shift_reg;
        end
     end

     assign sequence_detected = (next_shift_reg == 3'b111) || 
                                (next_shift_reg == 3'b101) || 
                                (next_shift_reg == 3'b110);

endmodule
